/**
 * Goal queue projection: when each unfunded ("queued") savings goal starts and
 * finishes, given that it is only saved towards once the goals ahead of it in
 * the queue are met. Active goals — those funded now by their linked budget
 * lines — project independently; as each completes, its fortnightly contribution
 * joins a growing "freed pool" that the queued goals draw from in order.
 */

import { projectGoal, type GoalProjection } from './goal.ts'
import {
  FORTNIGHT_MS,
  fortnightGrowthFactor,
  isoDate,
  MAX_FORTNIGHTS,
  requiredContributionCents,
} from './goalMath.ts'
import type { Money, SavingsGoal } from './index.ts'

/** An active goal: funded now by the summed contribution of its linked budget lines. */
export interface ActiveGoalFunding {
  readonly goal: SavingsGoal
  readonly fortnightlyContributionCents: Money
}

/** A queued goal: funded from freed capacity, optionally capped. */
export interface QueuedGoalFunding {
  readonly goal: SavingsGoal
  /** Cap on the fortnightly draw from the freed pool; null/absent draws the whole pool. */
  readonly plannedContributionCents?: Money | null
}

/** A queued goal's projected trajectory: `GoalProjection` plus when it starts drawing. */
export interface QueuedGoalProjection extends GoalProjection {
  /**
   * ISO date of the first fortnight the goal draws a positive amount from the
   * freed pool, or null when the pool never reaches it (no active goal, or none
   * completes) — the queue then has no projected start.
   */
  readonly projectedStartDate: string | null
}

/** The projections for a household's whole ordered goal list at one instant. */
export interface GoalQueueProjection {
  /** Parallel to the `active` input — each goal's own projection at its own rate. */
  readonly active: readonly GoalProjection[]
  /** Parallel to the `queued` input (already in queue order). */
  readonly queued: readonly QueuedGoalProjection[]
}

/**
 * The fortnight each active goal's contribution joins the freed pool, or null
 * when it never does — an unfunded goal, or one whose ETA runs past the
 * ~200-year walk, which is excluded rather than treated as blocking.
 */
function activeCompletionFortnights(projections: readonly GoalProjection[]): (number | null)[] {
  return projections.map((projection) => {
    const done = projection.fortnightsToTarget
    return done === null || done > MAX_FORTNIGHTS ? null : done
  })
}

/** The freed pool at fortnight `t`: the summed contribution of every active goal met by then. */
function poolAt(
  active: readonly ActiveGoalFunding[],
  completionFortnights: readonly (number | null)[],
  t: number,
): Money {
  let sum = 0
  for (let i = 0; i < active.length; i += 1) {
    const done = completionFortnights[i]!
    if (done !== null && done <= t) {
      sum += active[i]!.fortnightlyContributionCents
    }
  }
  return sum
}

/** One queued goal's running state through the fortnight-by-fortnight walk. */
interface QueuedState {
  readonly targetCents: Money
  readonly remainingCents: Money
  readonly growthFactor: number
  readonly capCents: number
  balanceCents: number
  contributedCents: number
  startFortnight: number | null
  doneFortnight: number | null
}

/** Seeds each queued goal's walk state; a goal already met starts done, drawing nothing. */
function seedQueuedStates(queued: readonly QueuedGoalFunding[]): QueuedState[] {
  return queued.map(({ goal, plannedContributionCents }) => {
    const remainingCents = Math.max(0, goal.targetAmountCents - goal.currentBalanceCents)
    return {
      targetCents: goal.targetAmountCents,
      remainingCents,
      growthFactor: fortnightGrowthFactor(goal.annualInterestBps),
      capCents: plannedContributionCents ?? Number.POSITIVE_INFINITY,
      balanceCents: goal.currentBalanceCents,
      contributedCents: 0,
      startFortnight: null,
      doneFortnight: remainingCents === 0 ? 0 : null,
    }
  })
}

/**
 * Advances the queued goals one fortnight: the freed pool is `availableCents`,
 * and each still-incomplete goal in turn draws `min(available, its cap)`,
 * growing its balance (by its factor when `withInterest`) before the draw is
 * added. A goal that fills mid-fortnight is clamped to its target and the
 * overshoot cascades to the next goal in the same fortnight, so no capacity is
 * lost. Mutates the states in place.
 */
function stepQueuedStates(
  states: readonly QueuedState[],
  availableCents: number,
  t: number,
  withInterest: boolean,
): void {
  let available = availableCents
  for (const state of states) {
    if (state.doneFortnight !== null) {
      continue
    }
    const draw = Math.min(available, state.capCents)
    if (draw > 0 && state.startFortnight === null) {
      state.startFortnight = t
    }
    const grown = withInterest ? state.balanceCents * state.growthFactor : state.balanceCents
    const nextBalance = withInterest ? Math.round(grown + draw) : grown + draw
    if (nextBalance >= state.targetCents) {
      state.doneFortnight = t
      const overshoot = nextBalance - state.targetCents
      state.balanceCents = state.targetCents
      const usedDraw = Math.max(0, draw - overshoot)
      state.contributedCents = Math.min(state.remainingCents, state.contributedCents + usedDraw)
      available -= usedDraw
    } else {
      state.balanceCents = nextBalance
      state.contributedCents = Math.min(state.remainingCents, state.contributedCents + draw)
      available -= draw
    }
    if (available <= 0) {
      break
    }
  }
}

/**
 * Walks the whole ordered list forward fortnight by fortnight, yielding each
 * queued goal's running state at the end of every fortnight until they are all
 * met or the ~200-year cap is reached. `withInterest` compounds a queued goal's
 * modelled rate on its running balance (so its ETA reflects growth); passing
 * `false` tracks contributions alone, for the net-worth cash line. Deterministic
 * — `now` is the only time input.
 */
export function* stepGoalQueue(
  active: readonly ActiveGoalFunding[],
  queued: readonly QueuedGoalFunding[],
  now: Date,
  withInterest: boolean,
): Generator<readonly QueuedState[]> {
  const states = seedQueuedStates(queued)
  const activeProjections = active.map((a) =>
    projectGoal(a.goal, a.fortnightlyContributionCents, now),
  )
  const completionFortnights = activeCompletionFortnights(activeProjections)
  // With no active goal ever completing, the pool stays empty and no queued goal
  // is ever drawn — the seeded states (a goal already met aside) are final.
  if (!completionFortnights.some((done) => done !== null)) {
    return
  }

  for (let t = 1; t <= MAX_FORTNIGHTS; t += 1) {
    if (states.every((state) => state.doneFortnight !== null)) {
      return
    }
    stepQueuedStates(states, poolAt(active, completionFortnights, t), t, withInterest)
    yield states
  }
}

/** Advances `now` by `fortnights` whole fortnights and formats the result as an ISO date. */
function fortnightDate(now: Date, fortnights: number): string {
  return isoDate(new Date(now.getTime() + fortnights * FORTNIGHT_MS))
}

/**
 * Projects a household's whole ordered goal list at `now`. Active goals project
 * independently at their own linked-line rate. The queued goals, in order, draw
 * from the pool freed as active goals complete: the first incomplete queued goal
 * takes `min(pool, plannedContributionCents)` each fortnight — the whole pool
 * when no cap is set — and the remainder cascades to the next. Per queued goal
 * the result carries its `projectedStartDate` (first fortnight it draws), its
 * `projectedCompletionDate`, and, for a dated goal, the
 * `requiredFortnightlyContributionCents` measured from that projected start.
 * When the pool never reaches a goal (no active goal, or none completes) its
 * dates and required contribution are all null.
 */
export function projectGoalQueue(
  active: readonly ActiveGoalFunding[],
  queued: readonly QueuedGoalFunding[],
  now: Date,
): GoalQueueProjection {
  const activeProjections = active.map((a) =>
    projectGoal(a.goal, a.fortnightlyContributionCents, now),
  )

  let finalStates: readonly QueuedState[] = seedQueuedStates(queued)
  for (const states of stepGoalQueue(active, queued, now, true)) {
    finalStates = states
  }

  const queuedProjections = queued.map(({ goal }, j): QueuedGoalProjection => {
    const state = finalStates[j]!
    const remainingCents = Math.max(0, goal.targetAmountCents - goal.currentBalanceCents)
    const alreadyMet = remainingCents === 0
    const fortnightsToTarget = state.doneFortnight
    const projectedCompletionDate =
      fortnightsToTarget === null ? null : fortnightDate(now, fortnightsToTarget)
    const startFortnight = alreadyMet ? 0 : state.startFortnight
    const projectedStartDate = startFortnight === null ? null : fortnightDate(now, startFortnight)

    let requiredFortnightlyContributionCents: Money | null = null
    if (goal.targetDate !== undefined && startFortnight !== null) {
      const startMs = now.getTime() + startFortnight * FORTNIGHT_MS
      const fortnightsLeft = Math.ceil((Date.parse(goal.targetDate) - startMs) / FORTNIGHT_MS)
      requiredFortnightlyContributionCents = requiredContributionCents(
        goal,
        goal.currentBalanceCents,
        fortnightsLeft,
      )
    }

    return {
      remainingCents,
      alreadyMet,
      fortnightsToTarget,
      projectedCompletionDate,
      projectedStartDate,
      requiredFortnightlyContributionCents,
    }
  })

  return { active: activeProjections, queued: queuedProjections }
}

/**
 * The total cash the queued goals have drawn from the freed pool by each
 * fortnight in `fortnights` (which must be ascending) — interest excluded, each
 * goal capped at its remaining-to-target. Feeds the net-worth projection's cash
 * line, which folds in a goal's future contributions but not its growth.
 */
export function queuedGoalCashByFortnight(
  active: readonly ActiveGoalFunding[],
  queued: readonly QueuedGoalFunding[],
  now: Date,
  fortnights: readonly number[],
): Money[] {
  const maxFortnight = fortnights.length > 0 ? Math.max(...fortnights) : 0
  if (queued.length === 0 || maxFortnight <= 0) {
    return fortnights.map(() => 0)
  }

  // Cumulative queued cash at each fortnight index (1-based; index 0 is 0).
  const cashByFortnight: Money[] = [0]
  let lastTotal = 0
  let fortnight = 0
  for (const states of stepGoalQueue(active, queued, now, false)) {
    fortnight += 1
    lastTotal = states.reduce((sum, state) => sum + state.contributedCents, 0)
    cashByFortnight[fortnight] = lastTotal
    if (fortnight >= maxFortnight) {
      break
    }
  }
  // The walk stops once every queued goal is met; hold its last total after that.
  for (let f = fortnight + 1; f <= maxFortnight; f += 1) {
    cashByFortnight[f] = lastTotal
  }

  return fortnights.map((f) => (f <= 0 ? 0 : cashByFortnight[Math.min(f, maxFortnight)]!))
}
